                f"audit line {line_no} must contain exactly the keys "
                "detail, hash, kind, prev, seq, source"
            )
        detail = data[DETAIL]
        kind = data[KIND]
        prev = data[PREV]
        seq = data[SEQ]
        source = data[SOURCE]
        digest = data[HASH]
        if not isinstance(detail, str) or detail == "":
            raise CorruptAuditError(
                f"audit line {line_no} detail must be a non-empty str"
            )
        if not isinstance(source, str) or source == "":
            raise CorruptAuditError(
                f"audit line {line_no} source must be a non-empty str"
            )
        if not isinstance(kind, str) or kind not in _KINDS:
            raise CorruptAuditError(
                f"audit line {line_no} kind must be one of local, merge, restore"
            )
        if not isinstance(prev, str):
            raise CorruptAuditError(f"audit line {line_no} prev must be a str")
        if not isinstance(digest, str):
            raise CorruptAuditError(f"audit line {line_no} hash must be a str")
        if isinstance(seq, bool) or not isinstance(seq, int):
            raise CorruptAuditError(f"audit line {line_no} seq must be an int")
        if seq != expected_seq:
            raise CorruptAuditError(
                f"audit line {line_no} seq is {seq}, expected {expected_seq}"
            )
