        handle.write(line)
        handle.flush()
        os.fsync(handle.fileno())

    if not existed:
        fd = os.open(os.path.dirname(os.path.abspath(path)), os.O_RDONLY)
        try:
            os.fsync(fd)
        finally:
            os.close(fd)

    return seq


